import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter/foundation.dart';
import 'package:photo_manager/photo_manager.dart';
import 'package:shared_preferences/shared_preferences.dart';

import 'gemini_config.dart';
import 'scanner.dart';
import 'theme.dart';

/// Clinical health report generated by Doctor AI (Gemini).
class DoctorPrescription {
  DoctorPrescription({
    required this.healthScore,
    required this.healthGrade,
    required this.diagnosis,
    required this.summary,
    required this.symptoms,
    required this.prescription,
    required this.potentialSavings,
    required this.isGeminiGenerated,
  });

  final int healthScore;
  final String healthGrade;
  final String diagnosis;
  final String summary;
  final List<String> symptoms;
  final String prescription;
  final String potentialSavings;
  final bool isGeminiGenerated;

  factory DoctorPrescription.fromJson(Map<String, dynamic> json, {required bool isGemini}) {
    return DoctorPrescription(
      healthScore: (json['healthScore'] as num?)?.toInt() ?? 80,
      healthGrade: json['healthGrade']?.toString() ?? 'B',
      diagnosis: json['diagnosis']?.toString() ?? 'Moderate Photo Congestion',
      summary: json['summary']?.toString() ?? 'Library diagnostics detected reclaimable duplicate media.',
      symptoms: (json['symptoms'] as List?)?.map((e) => e.toString()).toList() ?? [
        'Duplicate photo bursts consuming high storage',
        'Expired screenshot clutter',
      ],
      prescription: json['prescription']?.toString() ?? 'Perform 1-Tap Smart Clean to optimize storage.',
      potentialSavings: json['potentialSavings']?.toString() ?? 'Reclaimable Space',
      isGeminiGenerated: isGemini,
    );
  }
}

class GeminiService with ChangeNotifier {
  GeminiService._();
  static final GeminiService i = GeminiService._();

  static const String _prefKey = 'gemini_api_key_custom';
  String? _customKey;

  String? get apiKey {
    if (_customKey != null && _customKey!.trim().isNotEmpty) {
      return _customKey!.trim();
    }
    if (kGeminiApiKey.trim().isNotEmpty && kGeminiApiKey != 'PASTE_YOUR_GEMINI_API_KEY_HERE') {
      return kGeminiApiKey.trim();
    }
    return null;
  }

  bool get hasKey => apiKey != null && apiKey!.isNotEmpty;

  Future<void> init() async {
    final prefs = await SharedPreferences.getInstance();
    _customKey = prefs.getString(_prefKey);
    notifyListeners();
  }

  Future<void> saveApiKey(String key) async {
    final prefs = await SharedPreferences.getInstance();
    _customKey = key.trim();
    await prefs.setString(_prefKey, _customKey!);
    notifyListeners();
  }

  String? get maskedApiKey {
    final k = apiKey;
    if (k == null || k.isEmpty) return null;
    if (k.length <= 8) return '••••••••';
    return '${k.substring(0, 6)}...${k.substring(k.length - 4)}';
  }

  Future<void> clearApiKey() async {
    final prefs = await SharedPreferences.getInstance();
    _customKey = null;
    await prefs.remove(_prefKey);
    notifyListeners();
  }

  /// Full automated best shot picker that processes assets and returns the best index with Doctor AI reasoning.
  Future<({int bestIndex, String reason, bool isGemini})> analyzeBestShot(List<AssetEntity> assets) async {
    if (assets.length < 2) {
      return (bestIndex: 0, reason: 'Single candidate item.', isGemini: false);
    }

    if (hasKey) {
      try {
        final thumbs = <Uint8List>[];
        for (final a in assets.take(4)) {
          final data = await a.thumbnailDataWithSize(ThumbnailSize(512, 512));
          if (data != null) thumbs.add(data);
        }
        if (thumbs.length >= 2) {
          final visionResult = await pickBestShotWithVision(thumbs);
          if (visionResult != null) {
            return (
              bestIndex: visionResult.bestIndex,
              reason: visionResult.reason,
              isGemini: true,
            );
          }
        }
      } catch (e) {
        debugPrint('Gemini vision analysis error: $e');
      }
    }

    // High quality on-device heuristic fallback
    int bestIdx = 0;
    int maxPixelCount = 0;
    for (int i = 0; i < assets.length; i++) {
      final a = assets[i];
      final pixels = a.width * a.height;
      if (pixels > maxPixelCount) {
        maxPixelCount = pixels;
        bestIdx = i;
      }
    }

    return (
      bestIndex: bestIdx,
      reason: 'Doctor AI selected highest clarity shot with optimal composition.',
      isGemini: false,
    );
  }

  /// Generates a storage health prescription using Gemini 1.5 Flash.
  Future<DoctorPrescription> getPrescription(ScanResult result) async {
    final key = apiKey;
    if (key == null || key.isEmpty) {
      return _generateLocalPrescription(result);
    }

    try {
      final client = HttpClient();
      client.connectionTimeout = const Duration(seconds: 12);
      final uri = Uri.parse(
        'https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-lite-latest:generateContent?key=$key',
      );

      final request = await client.postUrl(uri);
      request.headers.contentType = ContentType.json;

      final prompt = '''
You are "Doctor AI", a luxury digital physician diagnosing an iPhone user's storage health.
Diagnostic Lab Metrics:
- Total Photos: ${result.stats.photoCount} (${formatBytes(result.stats.photoBytes)})
- Total Videos: ${result.stats.videoCount} (${formatBytes(result.stats.videoBytes)})
- Similar/Burst Photo Clusters: ${result.similar.length} clusters (${formatBytes(result.bytesOf(result.similarRemovable))} removable)
- Screenshots: ${result.screenshots.length} (${formatBytes(result.bytesOf(result.flat(result.screenshots)))})
- Blurry/Low Quality Photos: ${result.blurry.length} (${formatBytes(result.bytesOf(result.flat(result.blurry)))})
- Total Reclaimable Space: ${formatBytes(result.reclaimable)}

Diagnose this iPhone library and return strictly valid JSON matching this schema:
{
  "healthScore": 76,
  "healthGrade": "B+",
  "diagnosis": "Mild Storage Congestion",
  "summary": "Clinical evaluation indicates duplicate bursts and forgotten screenshots are crowding device performance.",
  "symptoms": [
    "${result.similar.length} similar bursts hoarding ${formatBytes(result.bytesOf(result.similarRemovable))}",
    "${result.screenshots.length} screenshots taking unnecessary memory"
  ],
  "prescription": "Administer 1-Tap Smart Clean to safely discharge ${formatBytes(result.reclaimable)} with zero memory loss.",
  "potentialSavings": "${formatBytes(result.reclaimable)}"
}
''';

      final requestBody = jsonEncode({
        'contents': [
          {
            'parts': [
              {'text': prompt}
            ]
          }
        ],
        'generationConfig': {
          'responseMimeType': 'application/json',
          'temperature': 0.3,
        }
      });

      request.write(requestBody);
      final response = await request.close();

      if (response.statusCode == 200) {
        final respBody = await response.transform(utf8.decoder).join();
        final data = jsonDecode(respBody) as Map<String, dynamic>;
        final candidates = data['candidates'] as List?;
        if (candidates != null && candidates.isNotEmpty) {
          final content = candidates[0]['content']?['parts']?[0]?['text'] as String?;
          if (content != null) {
            final parsed = jsonDecode(content) as Map<String, dynamic>;
            return DoctorPrescription.fromJson(parsed, isGemini: true);
          }
        }
      }
    } catch (e) {
      debugPrint('Gemini Prescription API error: $e');
    }

    return _generateLocalPrescription(result);
  }

  /// AI Best Shot Picker: Analyzes similar thumbnails using Gemini 1.5 Flash Vision.
  Future<({int bestIndex, String reason})?> pickBestShotWithVision(List<Uint8List> thumbnails) async {
    final key = apiKey;
    if (key == null || key.isEmpty || thumbnails.length < 2) {
      return null;
    }

    try {
      final client = HttpClient();
      client.connectionTimeout = const Duration(seconds: 10);
      final uri = Uri.parse(
        'https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-lite-latest:generateContent?key=$key',
      );

      final request = await client.postUrl(uri);
      request.headers.contentType = ContentType.json;

      final parts = <Map<String, dynamic>>[];
      for (final thumb in thumbnails) {
        parts.add({
          'inlineData': {
            'mimeType': 'image/jpeg',
            'data': base64Encode(thumb),
          }
        });
      }

      parts.add({
        'text': '''
You are "Doctor AI", an expert vision doctor.
These are ${thumbnails.length} similar candidate photos from an iPhone burst/sequence (indexed 0 to ${thumbnails.length - 1}).
Identify the SINGLE BEST photo based on:
1. Facial expression (eyes open, sharp smile, natural posture).
2. Sharpest focus (lowest motion blur/camera shake).
3. Best exposure and composition.

Respond strictly in valid JSON:
{
  "bestIndex": 0,
  "reason": "Sharpest eye focus and natural facial expression"
}
'''
      });

      final requestBody = jsonEncode({
        'contents': [
          {'parts': parts}
        ],
        'generationConfig': {
          'responseMimeType': 'application/json',
          'temperature': 0.2,
        }
      });

      request.write(requestBody);
      final response = await request.close();

      if (response.statusCode == 200) {
        final respBody = await response.transform(utf8.decoder).join();
        final data = jsonDecode(respBody) as Map<String, dynamic>;
        final candidates = data['candidates'] as List?;
        if (candidates != null && candidates.isNotEmpty) {
          final content = candidates[0]['content']?['parts']?[0]?['text'] as String?;
          if (content != null) {
            final parsed = jsonDecode(content) as Map<String, dynamic>;
            final bestIdx = (parsed['bestIndex'] as num?)?.toInt() ?? 0;
            final reason = parsed['reason']?.toString() ?? 'Doctor AI selected the best focal balance.';
            if (bestIdx >= 0 && bestIdx < thumbnails.length) {
              return (bestIndex: bestIdx, reason: reason);
            }
          }
        }
      }
    } catch (e) {
      debugPrint('Gemini Best Shot API error: $e');
    }

    return null;
  }

  /// High-fidelity on-device clinical prescription when API key is not yet set or offline.
  DoctorPrescription _generateLocalPrescription(ScanResult r) {
    final reclaimable = r.reclaimable;
    int score = 95;
    if (reclaimable > 10 * 1024 * 1024 * 1024) {
      score = 55;
    } else if (reclaimable > 5 * 1024 * 1024 * 1024) {
      score = 68;
    } else if (reclaimable > 2 * 1024 * 1024 * 1024) {
      score = 78;
    } else if (reclaimable > 500 * 1024 * 1024) {
      score = 86;
    }

    String grade = 'A';
    String diag = 'Pristine Storage State';
    if (score < 60) {
      grade = 'D+';
      diag = 'Severe Library Congestion';
    } else if (score < 75) {
      grade = 'C+';
      diag = 'Moderate Redundancy Detected';
    } else if (score < 85) {
      grade = 'B+';
      diag = 'Mild Duplicate Accumulation';
    }

    final symptoms = <String>[];
    if (r.similar.isNotEmpty) {
      symptoms.add('${r.similar.length} photo clusters holding ${formatBytes(r.bytesOf(r.similarRemovable))} in duplicates');
    }
    if (r.screenshots.isNotEmpty) {
      symptoms.add('${r.screenshots.length} screenshots taking ${formatBytes(r.bytesOf(r.flat(r.screenshots)))}');
    }
    if (r.blurry.isNotEmpty) {
      symptoms.add('${r.blurry.length} blurry/shaky shots degrading library quality');
    }
    if (symptoms.isEmpty) {
      symptoms.add('Zero acute clutter detected on local storage.');
      symptoms.add('Hardware memory is operating within optimal margins.');
    }

    return DoctorPrescription(
      healthScore: score,
      healthGrade: grade,
      diagnosis: diag,
      summary: 'Doctor AI diagnostic scan detected ${formatBytes(reclaimable)} eligible for safe reclamation.',
      symptoms: symptoms,
      prescription: 'Administer 1-Tap Smart Clean to discharge redundant assets while keeping all best moments.',
      potentialSavings: formatBytes(reclaimable),
      isGeminiGenerated: false,
    );
  }
}
